--
-- Table structure for table `system_notice`
--

DROP TABLE IF EXISTS `system_notice`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `system_notice` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '公告ID',
  `title` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '公告标题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '公告内容',
  `type` tinyint NOT NULL COMMENT '公告类型（1通知 2公告）',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '公告状态（0正常 1关闭）',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='通知公告表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `system_notice`
--

LOCK TABLES `system_notice` WRITE;
/*!40000 ALTER TABLE `system_notice` DISABLE KEYS */;
INSERT INTO `system_notice` VALUES (6,'夜间维护通知','<p class=\"ds-markdown-paragraph\"><strong><span class=\"\">重要通知 - 关于&ldquo;智云协同办公平台&rdquo;夜间停机维护升级的公告</span></strong></p>\n<p class=\"ds-markdown-paragraph\"><span class=\"\">尊敬的用户：</span></p>\n<p class=\"ds-markdown-paragraph\"><span class=\"\">为了给您提供更稳定、更高效的服务，我们计划于</span><strong><span class=\"\">2026年7月28日（周二）夜间</span></strong><span class=\"\">对平台核心数据库进行集群迁移与版本升级。届时，智云协同办公平台全部功能将暂停使用。</span></p>\n<p class=\"ds-markdown-paragraph\"><strong><span class=\"\">维护时间：</span></strong><br><strong><span class=\"\">2026年7月28日（周二） 23：00 至 7月29日（周三） 06：00</span></strong><br><span class=\"\">（如遇突发情况，维护时间可能顺延，我们将通过本公告及站内信及时同步进展。）</span></p>\n<p class=\"ds-markdown-paragraph\"><strong><span class=\"\">影响范围：</span></strong></p>\n<ol start=\"1\">\n<li>\n<p class=\"ds-markdown-paragraph\"><span class=\"\">维护期间，智云平台网页端、移动端App及小程序将</span><strong><span class=\"\">无法登录</span></strong><span class=\"\">。</span></p>\n</li>\n<li>\n<p class=\"ds-markdown-paragraph\"><span class=\"\">所有文档的在线编辑、保存、分享功能将</span><strong><span class=\"\">暂时中断</span></strong><span class=\"\">，未手动保存的内容可能丢失。</span></p>\n</li>\n<li>\n<p class=\"ds-markdown-paragraph\"><span class=\"\">审批流、任务指派及消息推送服务将</span><strong><span class=\"\">暂停</span></strong><span class=\"\">，待维护完成后统一恢复处理。</span></p>\n</li>\n<li>\n<p class=\"ds-markdown-paragraph\"><span class=\"\">API开放接口将返回503状态码，第三方集成应用暂时无法调取数据。</span></p>\n</li>\n</ol>\n<p class=\"ds-markdown-paragraph\"><strong><span class=\"\">请您务必提前完成以下操作：</span></strong></p>\n<ul>\n<li class=\"ds-markdown-paragraph\"><strong><span class=\"\">保存并关闭</span></strong><span class=\"\">当前正在编辑的所有文档、表格及设计稿（建议在</span><strong><span class=\"\">22：30前</span></strong><span class=\"\">完成）。</span></li>\n<li class=\"ds-markdown-paragraph\"><strong><span class=\"\">提交</span></strong><span class=\"\">待审批的流程单据，避免因停机导致审批超时。</span></li>\n<li class=\"ds-markdown-paragraph\"><strong><span class=\"\">导出</span></strong><span class=\"\">当日需要离线使用的重要数据报表。</span></li>\n</ul>\n<p class=\"ds-markdown-paragraph\"><span class=\"\">维护完成后，我们将第一时间恢复全部服务，并针对本次升级进行48小时稳定性监测。由此给您带来的不便，我们深表歉意，敬请谅解！</span></p>\n<p class=\"ds-markdown-paragraph\"><span class=\"\">如有紧急事务需要协助，请联系：</span></p>\n<ul>\n<li class=\"ds-markdown-paragraph\"><span class=\"\">技术支持热线：</span><strong><span class=\"\">400-888-9999</span></strong><span class=\"\">（维护期间仅受理紧急报障，不提供业务咨询）</span></li>\n<li class=\"ds-markdown-paragraph\"><span class=\"\">服务邮箱：</span><strong><span class=\"\">support@zhijun.com</span></strong></li>\n</ul>\n<p class=\"ds-markdown-paragraph\"><span class=\"\">感谢您的理解与支持！</span></p>\n<p class=\"ds-markdown-paragraph\"><span class=\"\">智云技术团队</span><br><span class=\"\">2026年7月28日</span></p>',1,0,'1','2026-07-28 17:37:23','1','2026-07-28 18:00:30',_binary '\0',1),(7,'ETS','<p>CS</p>\n<p>&nbsp;</p>',2,0,'1','2026-07-28 18:30:13','1','2026-07-28 18:31:06',_binary '',1);
/*!40000 ALTER TABLE `system_notice` ENABLE KEYS */;
UNLOCK TABLES;

